def decide(recipient_reputation, round_num, my_history):
    # Base threshold: start cautious, gradually become more cooperative
    if round_num < 10:
        base_threshold = 0.4 - 0.04 * round_num  # linear from 0.4 to 0.0
    else:
        base_threshold = 0.0
    # Adjust based on own cooperation history: higher own cooperation reduces threshold
    if len(my_history) > 0:
        recent = my_history[-5:] if len(my_history) >= 5 else my_history
        coop_recent = sum(1 for act in recent if act)
        coop_frac_recent = coop_recent / len(recent)
        # If we have been cooperative recently, lower the threshold
        if coop_frac_recent > 0.7:
            adjustment = -0.3
        elif coop_frac_recent < 0.3:
            adjustment = 0.1
        else:
            adjustment = -0.1
    else:
        adjustment = 0.0
    threshold = base_threshold + adjustment
    # Also boost threshold if we have cooperated a lot overall (don't be too gullible)
    total_coop = sum(1 for act in my_history if act)
    if total_coop > 15:
        threshold = min(0.3, threshold + 0.2)  # be somewhat more selective
    # Clamp threshold to reasonable range
    threshold = max(-0.5, min(0.5, threshold))
    return recipient_reputation >= threshold
